package za.co.loopmanager;

import android.app.Activity;
import android.content.res.ColorStateList;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.graphics.drawable.RippleDrawable;
import android.view.Gravity;
import android.view.View;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import com.google.android.material.bottomsheet.BottomSheetBehavior;
import com.google.android.material.bottomsheet.BottomSheetDialog;
import za.co.bacy.ui.BrandFonts;
import za.co.bacy.ui.InstrumentIcon;

/** Colour-coded native payment sheets. Financial actions remain with the enrolled account controller. */
final class AccountSheets {
 static final int INK=0xff000000,MUTED=0xff595959,TEAL=0xff000000,CORAL=0xff000000,GOLD=0xfff1f3f2,MINT=0xfff6f7f6,PAPER=0xffffffff,LINE=0xffdddddd;
 private final Activity activity;final BottomSheetDialog dialog;final LinearLayout body;
 private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 private AccountSheets(Activity a,String title,String subtitle){
  activity=a;dialog=new BottomSheetDialog(a);LinearLayout root=col();root.setBackgroundColor(PAPER);LinearLayout header=new LinearLayout(a);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(20),dp(18),dp(16),dp(16));TextView name=text(title,30,INK,true);name.setTypeface(BrandFonts.heading(a));name.setAccessibilityHeading(true);header.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView close=text("×",26,INK,false);close.setGravity(Gravity.CENTER);close.setContentDescription("Close sheet");close.setFocusable(true);close.setMinHeight(dp(48));close.setOnClickListener(v->dialog.dismiss());header.addView(close,new LinearLayout.LayoutParams(dp(48),dp(48)));root.addView(header);View rule=new View(a);rule.setBackgroundColor(INK);root.addView(rule,new LinearLayout.LayoutParams(-1,dp(2)));
  ScrollView scroll=new ScrollView(a);scroll.setFillViewport(false);scroll.setVerticalScrollBarEnabled(false);body=col();body.setPadding(dp(20),dp(20),dp(20),dp(32));scroll.addView(body);body.addView(text(subtitle,13,MUTED,false));gap(20);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));dialog.setContentView(root);
  dialog.setOnShowListener(d->{View sheet=dialog.findViewById(com.google.android.material.R.id.design_bottom_sheet);if(sheet!=null){sheet.setBackgroundColor(PAPER);android.view.ViewGroup.LayoutParams params=sheet.getLayoutParams();params.height=(int)(a.getResources().getDisplayMetrics().heightPixels*.88f);sheet.setLayoutParams(params);BottomSheetBehavior<View> behavior=BottomSheetBehavior.from(sheet);behavior.setSkipCollapsed(true);behavior.setState(BottomSheetBehavior.STATE_EXPANDED);}if(dialog.getWindow()!=null)dialog.getWindow().setDimAmount(.24f);});
 }
 private LinearLayout col(){LinearLayout l=new LinearLayout(activity);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private TextView text(String value,int size,int color,boolean bold){TextView v=new TextView(activity);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setTypeface(BrandFonts.sans(activity,bold));v.setLineSpacing(dp(2),1);v.setIncludeFontPadding(false);return v;}
 private GradientDrawable shape(int fill,int radius,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
 private void gap(int height){body.addView(new View(activity),new LinearLayout.LayoutParams(1,dp(height)));}
 private View action(String title,String detail,String icon,int fill,Runnable run){View row=AppControls.action(activity,title,detail,icon,fill,()->{dialog.dismiss();run.run();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(9);body.addView(row,p);return row;}
 private void pair(String a,String subA,String iconA,Runnable runA,String b,String subB,String iconB,Runnable runB){LinearLayout row=new LinearLayout(activity);String[] titles={a,b},subtitles={subA,subB},icons={iconA,iconB};Runnable[] actions={runA,runB};for(int i=0;i<2;i++){final int which=i;LinearLayout tile=col();tile.setPadding(dp(14),dp(16),dp(14),dp(16));tile.setMinimumHeight(dp(112));tile.setBackground(new RippleDrawable(ColorStateList.valueOf(0x1a075e55),shape(PAPER,9,LINE),null));tile.setFocusable(true);tile.setContentDescription(titles[i]);tile.setOnClickListener(v->{dialog.dismiss();actions[which].run();});tile.addView(new InstrumentIcon(activity,icons[i],TEAL),new LinearLayout.LayoutParams(dp(24),dp(24)));TextView title=text(titles[i],13,INK,true);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,-2);tp.topMargin=dp(12);tile.addView(title,tp);TextView sub=text(subtitles[i],11,MUTED,false);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(5);tile.addView(sub,sp);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);if(i==0)p.rightMargin=dp(10);row.addView(tile,p);}body.addView(row);}
 private void notice(String title,String message,int fill,String icon){LinearLayout card=col();card.setPadding(dp(14),dp(14),dp(14),dp(14));card.setBackground(shape(fill==CORAL?MINT:fill,3,LINE));LinearLayout top=new LinearLayout(activity);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(new InstrumentIcon(activity,icon,INK),new LinearLayout.LayoutParams(dp(20),dp(20)));TextView heading=text(title,18,INK,true);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(0,-2,1);hp.leftMargin=dp(10);top.addView(heading,hp);card.addView(top);TextView description=text(message,14,INK,false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);card.addView(description,p);body.addView(card);gap(16);}
 private void detail(String label,String value){LinearLayout row=col();row.setPadding(dp(2),dp(13),dp(2),dp(13));row.addView(text(label,12,MUTED,false));TextView reading=text(value,16,INK,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(5);row.addView(reading,p);body.addView(row);View line=new View(activity);line.setBackgroundColor(LINE);body.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}
 static AccountSheets panel(Activity a,String title,String subtitle){return new AccountSheets(a,title,subtitle);}
 AccountSheets note(String title,String message,int fill,String icon){notice(title,message,fill,icon);return this;}
 AccountSheets content(View view){body.addView(view);gap(16);return this;}
 AccountSheets line(String label,String value){detail(label,value);return this;}
 AccountSheets option(String title,String detail,String icon,int fill,Runnable run){action(title,detail,icon,fill,run);return this;}
 View formAction(String title,Runnable run){View v=AppControls.action(activity,title,"","message",MINT,run);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(10);body.addView(v,p);return v;}
 BottomSheetDialog show(){dialog.show();return dialog;}
 static BottomSheetDialog confirm(Activity a,String title,String message,String primary,Runnable action){return panel(a,title,"Please review before continuing").note(title,message,GOLD,"shield").option(primary,"","check",CORAL,action).show();}
 static BottomSheetDialog banks(Activity a,java.util.List<BankApps.Choice> banks,java.util.function.Consumer<BankApps.Choice> open){AccountSheets s=panel(a,"Banking","Open an installed banking app to pay or approve a payment.");android.widget.EditText search=new android.widget.EditText(a);search.setSingleLine(true);search.setHint("Find your bank");search.setTextSize(15);search.setTextColor(INK);search.setHintTextColor(MUTED);search.setTypeface(BrandFonts.sans(a,false));search.setPadding(s.dp(12),s.dp(12),s.dp(12),s.dp(12));search.setBackground(s.shape(PAPER,3,LINE));search.setMinHeight(s.dp(52));s.content(search);java.util.List<View> rows=new java.util.ArrayList<>();for(BankApps.Choice bank:banks){View row=s.action(bank.label,"Open banking app","bank",PAPER,()->open.accept(bank));try{android.widget.ImageView logo=new android.widget.ImageView(a);logo.setImageDrawable(a.getPackageManager().getApplicationIcon(bank.packageName));logo.setScaleType(android.widget.ImageView.ScaleType.FIT_CENTER);logo.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);LinearLayout layout=(LinearLayout)row;layout.removeViewAt(0);layout.addView(logo,0,new LinearLayout.LayoutParams(s.dp(26),s.dp(26)));}catch(android.content.pm.PackageManager.NameNotFoundException ignored){}rows.add(row);}TextView empty=s.text("No matching bank. Try another name.",14,MUTED,false);empty.setVisibility(View.GONE);s.body.addView(empty);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence v,int start,int count,int after){}public void onTextChanged(CharSequence v,int start,int before,int count){String query=v.toString().trim().toLowerCase(java.util.Locale.ROOT);int found=0;for(int i=0;i<rows.size();i++){boolean match=banks.get(i).label.toLowerCase(java.util.Locale.ROOT).contains(query);rows.get(i).setVisibility(match?View.VISIBLE:View.GONE);if(match)found++;}empty.setVisibility(found==0?View.VISIBLE:View.GONE);}public void afterTextChanged(android.text.Editable e){}});return s.show();}
 static BottomSheetDialog eft(Activity a,org.json.JSONObject bank,String reference,String amount,Runnable open,Runnable copy){AccountSheets s=panel(a,"Bank transfer","Manual EFT · approval follows settlement review");s.note(amount,"Use your exact payment reference. Your paid time changes after the administrator confirms the bank funds.",GOLD,"bank");if(bank!=null&&!bank.optString("account_number").isEmpty()){for(String[] f:new String[][]{{"Bank","bank"},{"Account holder","account_holder"},{"Account number","account_number"},{"Branch code","branch_code"}}){String value=bank.optString(f[1]);s.option(f[0]+": "+value,"Tap to copy","copy",PAPER,()->{a.getSystemService(android.content.ClipboardManager.class).setPrimaryClip(android.content.ClipData.newPlainText(f[0],value));AppControls.notice(a,f[0]+" copied");});}}else s.note("Account details needed","Ask your administrator for verified bank details before paying.",CORAL,"help");s.line("Payment reference",reference);s.option("Open banking app","Choose your installed bank","bank",MINT,open);s.option("Copy reference",reference,"copy",PAPER,copy);return s.show();}
 static BottomSheetDialog payments(Activity a,String amount,Runnable card,Runnable eft,Runnable manual,Runnable status,Runnable fresh){AccountSheets s=new AccountSheets(a,"Make a payment",amount+" due · choose how to pay");s.action("Card payment","Secure checkout with iKhokha","payment",CORAL,card);s.action("Instant EFT / Ozow","Choose your bank on secure checkout","bank",GOLD,eft);s.action("Bank transfer","Account details and your EFT reference","bank",MINT,manual);s.gap(4);s.pair("Payment status","Check confirmation","history",status,"Fresh payment link","Replace failed checkout","refresh",fresh);s.dialog.show();return s.dialog;}
 static BottomSheetDialog account(Activity a,String amount,String due,String grace,String reference,Runnable pay,Runnable copy){return account(a,amount,due,grace,reference,pay,copy,null);}
 static BottomSheetDialog account(Activity a,String amount,String due,String grace,String reference,Runnable pay,Runnable copy,Runnable summary){AccountSheets s=new AccountSheets(a,"Your plan","Your repayment agreement");s.notice(amount,"Every 30 days",MINT,"phone");s.detail("Next payment date",due);s.detail("Grace period ends",grace);s.detail("Your EFT reference",reference);s.gap(18);s.action("Make a payment","Card, Instant EFT or bank transfer","payment",CORAL,pay);s.action("Copy payment reference",reference,"copy",PAPER,copy);if(summary!=null)s.action("Copy payment summary","Total, verified paid amount, balance and progress","copy",GOLD,summary);s.dialog.show();return s.dialog;}
 static BottomSheetDialog status(Activity a,String state,boolean freshNeeded,String message,Runnable check,Runnable fresh,Runnable history){boolean paid="paid".equals(state);AccountSheets s=new AccountSheets(a,"Payment update","Confirmation comes directly from iKhokha");s.notice(paid?"Payment verified":freshNeeded?"A fresh link is needed":"review_required".equals(state)?"Needs a review":"none".equals(state)?"No checkout yet":"Waiting for confirmation",message,paid?MINT:freshNeeded?CORAL:GOLD,paid?"shield":"payment");if(paid)s.action("View payment history","Your approved payment records","history",MINT,history);else{s.action("Check again","Refresh the provider's payment status","refresh",MINT,check);if("pending".equals(state)||"failed".equals(state))s.action("Get a fresh payment link","Use if checkout failed and you were not debited","payment",CORAL,fresh);}s.dialog.show();return s.dialog;}
 static BottomSheetDialog fresh(Activity a,Runnable renew,Runnable check){AccountSheets s=new AccountSheets(a,"A fresh checkout","Check your bank before trying again");s.notice("Check before you retry","If your bank already debited you, check payment status first. Otherwise we will verify the old attempt before creating a new link for the amount due.",GOLD,"shield");s.action("Get fresh payment link","The server checks the old attempt first","payment",CORAL,renew);s.action("Check existing payment","Use this if your bank shows a debit","history",MINT,check);s.dialog.show();return s.dialog;}
 static BottomSheetDialog error(Activity a,String message){AccountSheets s=new AccountSheets(a,"Something needs attention","Your phone account");s.notice("Needs your attention",message,CORAL,"help");s.action("Got it","Return to your account","home",MINT,()->{});s.dialog.show();return s.dialog;}
}
